891.example_code:
# makeItem(netherite pickaxe, air, stone, minecraft:attribute_modifiers)
function makeItem(item: item, place: items, mine: items, hide: objects = "auto") :: item:
    if {_place::1} is not air:
        apply can place on adventure predicate to {_item}:
            blocks: {_place::*}
        if any of {_hide::*} is "auto":
            apply tooltip display component to {_item}:
                hide_tooltip: false
                hidden_components: can_place_on
    if {_mine::1} is not air:
        apply can break adventure predicate to {_item}:
            blocks: {_mine::*}
        if any of {_hide::*} is "auto":
            apply tooltip display component to {_item}:
                hide_tooltip: false
                hidden_components: can_place_on
    if any of {_hide::*} is not "auto":
        apply tooltip display component to {_item}:
            hide_tooltip: false
            hidden_components: {_hide::*}
    return {_item}

