# substring("abcdef", 3)
# -> abc...
function substring(string: string, letters: integer, dot: boolean = true) :: string:
    set {_result} to first {_letters} characters of {_string}
    if {_dot} is true:
        if length of {_string} is greater than {_letters}:
            set {_dotstring} to "..."
        else:
            set {_dotstring} to "" 
    else:
        set {_dotstring} to ""
    return "%{_result}%%{_dotstring}%"

