# Skript catches the Vanilla "/give" command and checks whether it is possible to give the player the amount of goods specified in the argument. 
on command "/give":
    set {_p} to arg-1 parsed as an player
    set {_c} to arg-3 parsed as number

    set {_i} to arg-2
    replace "minecraft:" with "" in {_i}
    replace "_" with " " in {_i}
    set {_i} to {_i} parsed as an item
    set {_stackSize} to maximum stack size of {_i}

# Check if the amount of items is possible to add to the player's inventory.
# → If it is not possible to add an amount of items to the player's inventory, then the event is cancelled.
    set {_x} to "%{_c}% %{_i}%" parsed as an item
    if player has not enough space for {_x}:
        cancel event
        set {_freeSlots} to 0
        set {_freeSpaceOnSlots} to 0

        loop integers from 0 to 35:
            if item in slot loop-number of {_p} is air:
                add 1 to {_freeSlots}

        set {_z} to amount of {_i} in {_p}'s inventory
        set {_z} to ({_z} / {_stackSize})
        set {_z} to (ceil({_z}) - {_z}) * {_stackSize}
        set {_maxItemCount} to ({_freeSlots} * {_stacksize}) + {_z}

# If the event was cancelled, then this script will retrieve the debug message with the amount of items player's inventory can handle. 
        send "&6 No free space on %{_p}%'s inventory for a &3%{_x}% !" to event-player
        send "&6 %{_p}%'s inventory can hold only &3&l%{_maxItemCount}%X %{_i}%" to event-player

