9456.example_code:
on inventory slot change:
	
	#| Prevent updates if changed item is air.
	event-item != 0 airs
	
	#| Do not change the {_ticks} variable to less than 1
	set {_ticks} to 5
	
	#| There is no secret behind what happens here, a player metadata "slot=<integer>" is defined when the event happens,
	#| setting it to the time it occurred, thus preventing a loop from happening in that small period in which the item was changed.
	if player's metadata "slot=%(index of event-slot)%" is not set:
		set player's metadata "slot=%(index of event-slot)%" to (now - (("%{_ticks}% ticks" parsed as timespan)))
	
	#| To prevent the loop from occurring, a check is made to find out when the event slot was last updated. 
	#| If the last time the slot was changed is greater than the time defined in the "{_ticks}" variable, then the item will update again.
	if (ticks of (difference between (player's metadata "slot=%(index of event-slot)%") and now)) >= {_ticks}:
		set player's metadata "slot=%(index of event-slot)%" to now
		
		#You can change the item returned from this function.
		set {_actualized-item} to Enchantments(event-item)
		
		#| Now with everything resolved, the slot in which the verification occurred is defined and updated as necessary, 
		#| because when the item does not undergo any update, the item is no longer updated, 
		#| thus avoiding defining the item all the time when the inventory is changing.
		set slot (index of event-slot) of player's inventory to {_actualized-item}
		
#Custom lore of Enchantments:
function Enchantments(item: item) :: item:
	if enchantments of {_item} is set:
		set item flags of {_item} to hide enchants
		loop (enchantments of {_item}):
			set {_info::*} to ("%loop-value%" parsed as "%string% %number%")
			set {_enchantment} to {_info::1}
			replace all """" with "" in {_enchantment}
			set {_level} to {_info::2}
			add "%nl% &8 | &7%{_enchantment}%&7: &b%{_level}%" to {_enchantments::*}
			
	set {_enchantments} to "&b📖 Enchantments&7: %concat({_enchantments::*})%"
	set lore of {_item} to concat({_enchantments}, {_lore::*})
	
	return {_item}

