function boundRadiusIntersect(b:object,loc:location,r:number) :: boolean:
    set {_dist} to {_r}^2
    set {_lx} to x-coord of {_loc}
    set {_ly} to y-coord of {_loc}
    set {_lz} to z-coord of {_loc}
    if {_lx} < {_b}.getMinX():
        subtract ({_lx} - {_b}.getMinX())^2 from {_dist}
    else if {_lx} > {_b}.getMaxX():
        subtract ({_lx} - {_b}.getMaxX())^2 from {_dist}
    if {_ly} < {_b}.getMinY():
        subtract ({_ly} - {_b}.getMinY())^2 from {_dist}
    else if {_ly} > {_b}.getMaxY():
        subtract ({_ly} - {_b}.getMaxY())^2 from {_dist}
    if {_lz} < {_b}.getMinZ():
