# Zackwall on discord
# Minecraft has a limit of 32x32x32 for placing structures in servers, so if you were wondering why your structures aren't saving/placing its because of the limit that Minecraft placed on structures. In order to place large structures you need to save them by chunks, Below is an example on how you can place large structures, check the example in https://skripthub.net/docs/?id=10552 on how to save the chunks first

# Determine the boundaries of the area
set {_minX} to min(x-coord of {_position1}, x-coord of {_position2})
set {_minY} to min(y-coord of {_position1}, y-coord of {_position2})
set {_minZ} to min(z-coord of {_position1}, z-coord of {_position2})

set {_maxX} to max(x-coord of {_position1}, x-coord of {_position2})
set {_maxY} to max(y-coord of {_position1}, y-coord of {_position2})
set {_maxZ} to max(z-coord of {_position1}, z-coord of {_position2})

# Loop through chunks to load them
set {_x} to {_minX}
while {_x} <= {_maxX}:
    set {_y} to {_minY}
    while {_y} <= {_maxY}:
        set {_z} to {_minZ}
        while {_z} <= {_maxZ}:
            set {_chunkName} to "structure_NAME_%{_x}%_%{_y}%_%{_z}%"

            # Load the structure
            set {_structure} to structure named "%{_chunkName}%"
            set structure include entities of {_structure} to false # preference
            place structure {_structure} at location({_x}, {_y}, {_z})

            add 32 to {_z}
        add 32 to {_y}
    add 32 to {_x}

